#include <bits/stdc++.h>

using ull = unsigned long long;
constexpr ull LIMIT = 17446744073709551616ULL;

ull MOD, dp[18][250005], fact[250005], invfact[250005];
ull N, K;

inline ull power(ull base, ull exp) {
    ull res = 1;
    while (exp) {
        if (exp & 1ULL) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1ULL;
    }
    return res;
}

inline ull binom(int a, int b) {
    return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD;
}

ull solveInner() {
    fact[0] = 1;
    for (int i = 1; i <= N; ++i)
        fact[i] = fact[i - 1] * (ull)i % MOD;

    invfact[N] = power(fact[N], MOD - 2);
    for (int i = (int)N - 1; i >= 0; --i)
        invfact[i] = invfact[i + 1] * (ull)(i + 1) % MOD;

    for (int i = 1; i <= N; ++i)
        dp[1][i] = invfact[i];

    ull ans = dp[1][N] * binom((int)K, 1) % MOD;
    int t = (17 < (int)K ? 17 : (int)K);

    for (int i = 2; i <= t; ++i) {
        for (int j = N; j; j = (j - 1) & N) {
            ull cur = 0;
            for (int l = j; l; l = (l - 1) & j) {
                cur += dp[i - 1][j ^ l] * invfact[l];
                if (cur > LIMIT) cur %= MOD;
            }
            dp[i][j] = cur % MOD;
        }
        ans = (ans + dp[i][N] * binom((int)K, i)) % MOD;
    }

    ans = ans * fact[N] % MOD;
    return ans;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::cin >> N >> K >> MOD;
    ull ans = power(K, N);
    if (N & 1ULL) {
        std::cout << ans << '\n';
        return 0;
    }
    ans = (ans - solveInner() + MOD) % MOD;
    std::cout << ans << '\n';
    return 0;
}
